return [
  {
    json: {
      send_status: 'letter_review',
      queue_label: 'ТРЕБУЕТ ПРОВЕРКИ',
      batch_size: 10,
    },
  },
];

const settings = $('Telegram Settings').first().json;
const batchSize = Math.max(
  1,
  Number(settings.batch_size || 1)
);

function parseObject(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

const rows = $input.all()
  .map((item) => {
    const vacancy = { ...item.json };
    const analysis = parseObject(vacancy.analysis_json);

    const evaluation =
      analysis.evaluation &&
      typeof analysis.evaluation === 'object'
        ? analysis.evaluation
        : analysis;

    const generation =
      analysis.cover_letter_generation &&
      typeof analysis.cover_letter_generation === 'object'
        ? analysis.cover_letter_generation
        : {};

    const score = Number.isFinite(Number(vacancy.score))
      ? Number(vacancy.score)
      : Number(evaluation.score || 0);

    const decision = String(
      evaluation.decision ||
        (score >= 75
          ? 'recommend'
          : score >= 60
            ? 'review'
            : 'reject')
    );

    vacancy.telegram_queue_label = String(
      settings.queue_label || ''
    );
    vacancy.telegram_score = score;
    vacancy.telegram_decision = decision;
    vacancy.telegram_warnings = Array.isArray(
      generation.warnings
    )
      ? generation.warnings
      : [];

    return vacancy;
  })
  .filter((vacancy) => {
    return (
      typeof vacancy.cover_letter === 'string' &&
      vacancy.cover_letter.trim() &&
      !String(vacancy.telegram_message_id || '').trim()
    );
  })
  .sort((a, b) => {
    if (b.telegram_score !== a.telegram_score) {
      return b.telegram_score - a.telegram_score;
    }

    return String(b.published_at || '').localeCompare(
      String(a.published_at || '')
    );
  })
  .slice(0, batchSize);

return rows.map((vacancy) => ({
  json: vacancy,
}));

const vacancy = { ...$json };

function clean(value) {
  return String(value || '')
    .replace(/\u00a0/g, ' ')
    .replace(/[\u2013\u2014\u2212]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\u2022/g, '-')
    .replace(/\u2192/g, '->')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const warnings = Array.isArray(vacancy.telegram_warnings)
  ? vacancy.telegram_warnings
      .map(clean)
      .filter(Boolean)
      .slice(0, 5)
  : [];

const warningBlock =
  warnings.length > 0
    ? [
        '',
        'ПРЕДУПРЕЖДЕНИЯ:',
        ...warnings.map((warning) => `- ${warning}`),
      ].join('\n')
    : '';

const message = [
  clean(vacancy.telegram_queue_label),
  '',
  clean(vacancy.title),
  clean(vacancy.company),
  '',
  `Score: ${Number(vacancy.telegram_score || 0)}`,
  `Decision: ${clean(vacancy.telegram_decision)}`,
  `Резюме: ${clean(vacancy.recommended_resume)}`,
  `Зарплата: ${clean(vacancy.salary || 'не указана')}`,
  `Локация: ${clean(vacancy.location || 'не указана')}`,
  `Формат: ${clean(vacancy.work_format || 'unspecified')}`,
  warningBlock,
  '',
  `Вакансия: ${clean(vacancy.url)}`,
  '',
  'СОПРОВОДИТЕЛЬНОЕ ПИСЬМО:',
  '',
  clean(vacancy.cover_letter),
].filter((line, index, array) => {
  if (line !== '') {
    return true;
  }

  return index === 0 || array[index - 1] !== '';
}).join('\n');

if (!message.trim()) {
  throw new Error(
    `Empty Telegram message for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

if (message.length > 3900) {
  throw new Error(
    `Telegram message is too long for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }: ${message.length} characters`
  );
}

vacancy.telegram_text = message;

return {
  json: vacancy,
};

const source = {
  ...$('Build Telegram Message').item.json,
};

const telegramResponse = { ...$json };

const messageId =
  telegramResponse.message_id ??
  telegramResponse.result?.message_id ??
  telegramResponse.messageId ??
  '';

if (!String(messageId).trim()) {
  throw new Error(
    `Telegram message_id is missing for vacancy ${
      source.vacancy_id || 'unknown'
    }`
  );
}

source.telegram_message_id = String(messageId);
source.telegram_previous_status = String(source.status || '');
source.status = 'sent_to_telegram';
source.updated_at = $now.toUTC().toISO();
source.last_error = '';

delete source.telegram_text;
delete source.telegram_queue_label;
delete source.telegram_score;
delete source.telegram_decision;
delete source.telegram_warnings;

return {
  json: source,
};

return $input.all().map((item) => {
  const vacancy = item.json;

  return {
    json: {
      vacancy_id: String(vacancy.vacancy_id || ''),
      title: String(vacancy.title || ''),
      company: String(vacancy.company || ''),
      previous_status: String(
        vacancy.telegram_previous_status || ''
      ),
      status: String(vacancy.status || ''),
      telegram_message_id: String(
        vacancy.telegram_message_id || ''
      ),
      url: String(vacancy.url || ''),
    },
  };
});

const token = String($env.PANEVIN_BOT || '').trim();
const adminId = String($env.PANEVIN_ADMIN_ID || '401063682').trim();
const plainText = String($json.telegram_text || '').trim();

if (!token) {
  throw new Error('PANEVIN_BOT is empty');
}

if (!adminId) {
  throw new Error('PANEVIN_ADMIN_ID is empty');
}

if (!plainText) {
  throw new Error(`telegram_text is empty for vacancy ${$json.vacancy_id || 'unknown'}`);
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const marker = 'СОПРОВОДИТЕЛЬНОЕ ПИСЬМО:';
const markerIndex = plainText.indexOf(marker);

let telegramHtml;

if (markerIndex >= 0) {
  const header = plainText
    .slice(0, markerIndex)
    .trim();

  const coverLetter = plainText
    .slice(markerIndex + marker.length)
    .trim();

  if (!coverLetter) {
    throw new Error(
      `Cover letter is empty for vacancy ${$json.vacancy_id || 'unknown'}`
    );
  }

  telegramHtml = [
    escapeHtml(header),
    '',
    `<b>${marker}</b>`,
    `<pre>${escapeHtml(coverLetter)}</pre>`,
  ].join('\n');
} else {
  telegramHtml = escapeHtml(plainText);
}

if (telegramHtml.length > 12000) {
  throw new Error(
    `Telegram HTML payload is unexpectedly large for vacancy ${$json.vacancy_id || 'unknown'}: ${telegramHtml.length}`
  );
}

let response;

try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${token}/sendMessage`,
    headers: {
      'Content-Type': 'application/json',
    },
    body: {
      chat_id: adminId,
      text: telegramHtml,
      parse_mode: 'HTML',
      link_preview_options: {
        is_disabled: true,
      },
    },
    json: true,
  });
} catch (error) {
  const safeMessage = String(error?.message || error || 'Unknown Telegram error')
    .split(token)
    .join('[REDACTED_BOT_TOKEN]');

  throw new Error(
    `Telegram send failed for vacancy ${$json.vacancy_id || 'unknown'}: ${safeMessage}`
  );
}

if (!response?.ok || !response?.result?.message_id) {
  throw new Error(
    `Unexpected Telegram response for vacancy ${$json.vacancy_id || 'unknown'}: ${JSON.stringify(response)}`
  );
}

return {
  json: {
    ...$json,
    telegram_text_html: telegramHtml,
    telegram_api_response: response.result,
    message_id: response.result.message_id,
    telegram_message_id: response.result.message_id,
  },
};
